 \begin{align*}
2^3\cdot3^x&=72\\
2^3\cdot3^x&=2^3\cdot2\cdot3\cdot3\\
\text{By the Quotient Rule,}\quad 3^x&=2\cdot3\\
\text{By the Product Rule,}\quad 3^x&=2^3\\
\text{Thus,}\quad x&=\boxed{3}.
\end{align*}
